//! A concrete interface-export computation policy, applied after specialization.
//! This is neither a package principal nor a promise about future templates or
//! later invocation of returned callables. The trusted caller pins the compiler.
//! Admission owns its exact proof, is not cloneable or serializable, and can only
//! emit/open a native object against that proof after checking current policy.
use crate::{diagnostic::Diagnostic, diagnostic::Span, native, reuse, runtime, sha256};
use crate::check::units::{CheckedUnit, Dependency, Interface};

pub struct Policy { allowed: Vec<String>, identity: String }
#[derive(Clone, PartialEq, Eq)]
pub struct Binding {
    producer: Vec<u8>, name: String, input: String, body: String,
    interface: String, dependencies: Vec<Dependency>,
}
enum Proof { Checked(CheckedUnit), Authenticated(Interface) }
pub struct Admission { proof: Proof, binding: Binding, policy: String }

fn error(code: &str, detail: &str) -> Diagnostic {
    Diagnostic::new(Span::default(), code, detail)
}
fn policy(allowed: Vec<String>) -> Policy {
    let mut bytes = b"lkjscript-concrete-export-computation-1\n"[..].to_vec();
    for operation in &allowed {
        bytes.extend_from_slice(operation.as_bytes());
        bytes.push(b'\n');
    }
    Policy { allowed, identity: sha256::hex_digest(&bytes) }
}
pub fn computation_v1() -> Policy {
    let allowed = vec!["array_repeat".to_string(), "assert".to_string(), "box_new".to_string(),
        "cast".to_string(), "char_from_u32".to_string(), "clone".to_string(),
        "f64_from_bits".to_string(), "f64_to_bits".to_string(), "replace".to_string(),
        "str_as_bytes".to_string(), "str_from_utf8".to_string(), "str_len".to_string(),
        "vec_len".to_string(), "vec_new".to_string(), "vec_pop".to_string(), "vec_push".to_string()];
    policy(allowed)
}
impl Policy {
    pub fn identity(&self) -> &str { self.identity.as_str() }
    /// The public policy constructor can only narrow the closed v1 allowlist.
    pub fn without(&self, operation: &str) -> Result<Policy, Diagnostic> {
        let mut allowed = Vec::new();
        let mut found = false;
        for name in &self.allowed {
            if name.as_str() == operation { found = true; }
            else { allowed.push(name.clone()); }
        }
        if !found { return Err(error("E_COMPUTATION_POLICY", "operation is not allowed by this policy")); }
        Ok(policy(allowed))
    }
}
impl Binding {
    /// This metadata is not approval. Its compiler identity is trusted caller input.
    pub fn new(producer: &[u8], interface: &Interface) -> Result<Binding, Diagnostic> {
        if producer.len() != 32usize {
            return Err(error("E_COMPUTATION_PRODUCER", "expected compiler identity must contain exactly 32 bytes"));
        }
        Ok(Binding { producer: producer.to_vec(), name: interface.name().to_string(),
            input: interface.input_identity().to_string(), body: interface.body_identity().to_string(),
            interface: interface.identity().to_string(), dependencies: interface.dependencies().to_vec() })
    }
}
fn audit(interface: &Interface, selected: &Policy) -> Result<(), Diagnostic> {
    if interface.program().functions.is_empty() {
        return Err(error("E_COMPUTATION_EMPTY", "no concrete interface function is selected"));
    }
    for index in 0usize..interface.program().functions.len() {
        for operation in interface.effects(index) {
            if !selected.allowed.contains(operation) {
                return Err(error("E_COMPUTATION_EFFECT", &format!("{} requires refused operation {}",
                    interface.program().functions[index].name, operation)));
            }
        }
    }
    Ok(())
}
pub fn checked(unit: CheckedUnit, producer: &[u8], selected: &Policy) -> Result<Admission, Diagnostic> {
    audit(unit.interface(), selected)?;
    let binding = Binding::new(producer, unit.interface())?;
    Ok(Admission { proof: Proof::Checked(unit), binding, policy: selected.identity.clone() })
}
/// Authentication restores checker facts; the current policy is evaluated again.
pub fn authenticated(expected: &Binding, secret: &[u8], envelope: &[u8], selected: &Policy)
    -> Result<Admission, Diagnostic> {
    let interface = Interface::authenticate(&expected.producer, secret, &expected.name,
        &expected.input, &expected.dependencies, envelope)
        .ok_or_else(|| error("E_COMPUTATION_AUTH", "interface authentication or expected input failed"))?;
    if Binding::new(&expected.producer, &interface)? != *expected {
        return Err(error("E_COMPUTATION_BINDING", "interface body or semantic identity differs from the expected binding"));
    }
    audit(&interface, selected)?;
    Ok(Admission { proof: Proof::Authenticated(interface), binding: expected.clone(), policy: selected.identity.clone() })
}
impl Admission {
    fn interface(&self) -> &Interface {
        match &self.proof { Proof::Checked(unit) => unit.interface(), Proof::Authenticated(interface) => interface }
    }
    pub fn binding(&self) -> &Binding { &self.binding }
    pub fn policy_identity(&self) -> &str { self.policy.as_str() }
    fn current(&self, expected: &Binding, selected: &Policy) -> Result<(), Diagnostic> {
        if self.binding != *expected || Binding::new(&expected.producer, self.interface())? != *expected {
            return Err(error("E_COMPUTATION_BINDING", "admission belongs to a different exact unit or compiler"));
        }
        audit(self.interface(), selected)?;
        if self.policy != selected.identity {
            return Err(error("E_COMPUTATION_POLICY", "policy changed; admit again under the current policy"));
        }
        Ok(())
    }
    /// Consuming cold path: emission receives exactly the checked proof that passed.
    pub fn emit(self, expected: &Binding, selected: &Policy, runtime: &runtime::Runtime,
        source_base: usize) -> Result<native::units::Object, Diagnostic> {
        self.current(expected, selected)?;
        match self.proof {
            Proof::Checked(unit) => native::units::emit(&unit, runtime, source_base),
            Proof::Authenticated(_) => Err(error("E_COMPUTATION_BODY", "interface authentication cannot fabricate a checked body")),
        }
    }
    /// Consuming reuse path: no caller-supplied replacement interface is accepted.
    /// The object envelope must bind this compiler, key, body, ABI and source table.
    pub fn open(self, expected: &Binding, selected: &Policy, runtime: &runtime::Runtime,
        source_base: usize, sources: &[String], secret: &[u8], envelope: &[u8])
        -> Result<native::units::Object, Diagnostic> {
        self.current(expected, selected)?;
        let key = native::units::object_key(self.interface(), runtime, source_base, sources);
        let header = reuse::header_size();
        if envelope.len() < header {
            return Err(error("E_COMPUTATION_OBJECT", "native object envelope is truncated"));
        }
        let root = reuse::AuthenticatedRoot::new(&expected.producer, secret,
            native::units::namespace(), &key, &envelope[..header])
            .ok_or_else(|| error("E_COMPUTATION_OBJECT", "native object authentication failed"))?;
        let payload = root.verify(envelope[header..].to_vec())
            .ok_or_else(|| error("E_COMPUTATION_OBJECT", "native object payload differs"))?;
        let domain = reuse::ProofDomain::new(&expected.producer, secret);
        native::units::Object::open(&domain, self.interface(), runtime, source_base, sources, payload)
            .ok_or_else(|| error("E_COMPUTATION_OBJECT", "native object is incompatible with the exact admitted interface"))
    }
}

//! Source-specialization, authenticated reuse and native consumption controls.
use crate::{check, ir, ir_text, native, reuse, runtime, programs_unit_policy as policy};
use crate::check::units::{CheckedUnit, Import, Interface};

fn read(world: &mut World, path: &str) -> Vec<u8> {
    let mut root = world.directory(".").unwrap();
    let mut file = root.open(path).unwrap();
    file.read_to_end().unwrap()
}
fn fixture(world: &mut World, root: &str, name: &str) -> CheckedUnit {
    let text = String::from_utf8(read(world, &format!("{root}/{name}.lkjir"))).unwrap();
    let bytes = text.as_bytes();
    let input = crate::sha256::hex_digest(bytes);
    let program = ir_text::read(&text).unwrap();
    let mut exports = Vec::new();
    for (index, function) in program.functions.iter().enumerate() {
        if function.name == "entry" { exports.push(index); }
    }
    assert_eq!(exports.len(), 1usize);
    let imports: Vec<Import> = Vec::new();
    check::units::check_unit_with_exports(name, &input, program, &imports, &exports, &[0usize; 0]).unwrap()
}
fn effect(interface: &Interface, operation: &str) -> bool {
    for index in 0usize..interface.program().functions.len() {
        for found in interface.effects(index) { if found.as_str() == operation { return true; } }
    }
    false
}
fn producer(text: &str) -> Vec<u8> {
    let mut bytes = Vec::new();
    assert_eq!(text.len(), 64usize);
    for pair in 0usize..32usize {
        let mut value = 0u8;
        for offset in 0usize..2usize {
            let byte = text.as_bytes()[pair * 2usize + offset];
            let digit = if byte >= b'0' && byte <= b'9' { byte - b'0' }
                else { assert!(byte >= b'a' && byte <= b'f'); byte - b'a' + 10u8 };
            value = value * 16u8 + digit;
        }
        bytes.push(value);
    }
    bytes
}
fn runtime(world: &mut World, root: &str) -> runtime::Runtime {
    let text = String::from_utf8(read(world, &format!("{root}/runtime.lkjir"))).unwrap();
    runtime::seal(check::check(ir_text::read(&text).unwrap()).unwrap()).unwrap()
}
fn execute(world: &mut World, mut file: File) -> i64 {
    file.set_executable().unwrap();
    let input = world.temporary_file().unwrap();
    let output = world.temporary_file().unwrap();
    let errors = world.temporary_file().unwrap();
    let mut result = world.temporary_file().unwrap();
    let arguments: Vec<Vec<u8>> = Vec::new();
    let mut process = world.process();
    let mut child = process.spawn_file(&file, &arguments, &input, &output, &errors, &result).unwrap();
    assert_eq!(child.wait().unwrap(), 0i64);
    result.rewind().unwrap();
    let bytes = result.read_to_end().unwrap();
    assert_eq!(bytes.len(), 8usize);
    let mut value = 0u64;
    for index in 0usize..8usize { value |= (bytes[index] as u64) << (index * 8usize); }
    value as i64
}
fn linked(world: &mut World, runtime: &runtime::Runtime, interface: &Interface,
    object: native::units::Object, sources: &[String], messages: &[String]) -> i64 {
    let mut linker = native::units::Linker::new(world.temporary_file().unwrap(), world.temporary_file().unwrap()).unwrap();
    linker.push(object).unwrap();
    let grants: Vec<ir::EntryGrant> = Vec::new();
    let (file, _) = linker.finish(runtime, interface, "entry", &grants, sources, messages, Some(3u32)).unwrap();
    execute(world, file)
}
fn positive_and_reuse(world: &mut World, root: &str, producer: &[u8], runtime: &runtime::Runtime) -> usize {
    let selected = policy::computation_v1();
    let secret = [19u8; 32];
    let unit = fixture(world, root, "compute");
    let interface = unit.interface().clone();
    assert!(effect(&interface, "vec_new"));
    assert!(effect(&interface, "str_len"));
    let sources = unit.program().sources.clone();
    let messages = native::messages(unit.program());
    let expected = policy::Binding::new(producer, &interface).unwrap();
    let envelope = interface.seal(producer, &secret);
    let admitted = policy::checked(unit, producer, &selected).unwrap();
    assert_eq!(admitted.policy_identity(), selected.identity());
    assert!(*admitted.binding() == expected);
    let object = admitted.emit(&expected, &selected, runtime, 0usize).unwrap();
    let bytes = object.encode();
    let object_envelope = reuse::seal(producer, &secret, native::units::namespace(), object.key(), &bytes);
    assert_eq!(linked(world, runtime, &interface, object, &sources, &messages), 9i64);
    let restored = policy::authenticated(&expected, &secret, &envelope, &selected).unwrap();
    let object = restored.open(&expected, &selected, runtime, 0usize, &sources, &secret, &object_envelope).unwrap();
    assert_eq!(object.encode(), bytes);
    assert_eq!(linked(world, runtime, &interface, object, &sources, &messages), 9i64);
    let narrower = selected.without("vec_new").unwrap();
    assert!(selected.identity() != narrower.identity());
    assert!(Interface::authenticate(producer, &secret, interface.name(), interface.input_identity(),
        interface.dependencies(), &envelope).is_some());
    assert_eq!(policy::authenticated(&expected, &secret, &envelope, &narrower).err().unwrap().code, "E_COMPUTATION_EFFECT");
    let restored = policy::authenticated(&expected, &secret, &envelope, &selected).unwrap();
    assert_eq!(restored.open(&expected, &narrower, runtime, 0usize, &sources, &secret, &object_envelope)
        .err().unwrap().code, "E_COMPUTATION_EFFECT");
    let restored = policy::authenticated(&expected, &secret, &envelope, &selected).unwrap();
    assert_eq!(restored.emit(&expected, &selected, runtime, 0usize).err().unwrap().code, "E_COMPUTATION_BODY");
    let mut changed = bytes.clone(); changed.push(0u8);
    let bad_object = reuse::seal(producer, &secret, native::units::namespace(),
        &native::units::object_key(&interface, runtime, 0usize, &sources), &changed);
    let restored = policy::authenticated(&expected, &secret, &envelope, &selected).unwrap();
    assert_eq!(restored.open(&expected, &selected, runtime, 0usize, &sources, &secret, &bad_object)
        .err().unwrap().code, "E_COMPUTATION_OBJECT");
    let restored = policy::authenticated(&expected, &secret, &envelope, &selected).unwrap();
    assert_eq!(restored.open(&expected, &selected, runtime, 1usize, &sources, &secret, &object_envelope)
        .err().unwrap().code, "E_COMPUTATION_OBJECT");
    let restored = policy::authenticated(&expected, &secret, &envelope, &selected).unwrap();
    assert_eq!(restored.open(&expected, &selected, runtime, 0usize, &sources, &[20u8; 32], &object_envelope)
        .err().unwrap().code, "E_COMPUTATION_OBJECT");
    8usize
}
fn negatives(world: &mut World, root: &str, producer: &[u8]) -> usize {
    let selected = policy::computation_v1();
    let mut count = 0usize;
    let cases = vec![("file".to_string(), "read_directory_open".to_string()),
        ("socket".to_string(), "connector_connect".to_string()),
        ("callback".to_string(), "stdout_write".to_string()),
        ("custom_drop".to_string(), "stdout_write".to_string()),
        ("structural_drop".to_string(), "file_close".to_string())];
    for (name, operation) in cases {
        let unit = fixture(world, root, name.as_str());
        assert!(effect(unit.interface(), operation.as_str()));
        assert_eq!(policy::checked(unit, producer, &selected).err().unwrap().code, "E_COMPUTATION_EFFECT");
        count += 1usize;
    }
    count
}
fn callback_positive(world: &mut World, root: &str, producer: &[u8], runtime: &runtime::Runtime) -> usize {
    let unit = fixture(world, root, "callback_pure");
    let interface = unit.interface().clone();
    let sources = unit.program().sources.clone();
    let messages = native::messages(unit.program());
    let selected = policy::computation_v1();
    let expected = policy::Binding::new(producer, &interface).unwrap();
    let object = policy::checked(unit, producer, &selected).unwrap().emit(&expected, &selected, runtime, 0usize).unwrap();
    assert_eq!(linked(world, runtime, &interface, object, &sources, &messages), 42i64);
    1usize
}
fn binding_and_policy_changes(world: &mut World, root: &str, producer: &[u8], runtime: &runtime::Runtime) -> usize {
    let selected = policy::computation_v1();
    let narrower = selected.without("vec_new").unwrap();
    let unit = fixture(world, root, "literal");
    let interface = unit.interface().clone();
    let expected = policy::Binding::new(producer, &interface).unwrap();
    let wrong = policy::Binding::new(&[3u8; 32], &interface).unwrap();
    let admission = policy::checked(unit, producer, &selected).unwrap();
    assert_eq!(admission.emit(&wrong, &selected, runtime, 0usize).err().unwrap().code, "E_COMPUTATION_BINDING");
    let admission = policy::checked(fixture(world, root, "literal"), producer, &selected).unwrap();
    assert_eq!(admission.emit(&expected, &narrower, runtime, 0usize).err().unwrap().code, "E_COMPUTATION_POLICY");
    let admission = policy::checked(fixture(world, root, "literal"), producer, &narrower).unwrap();
    assert!(admission.emit(&expected, &narrower, runtime, 0usize).is_ok());
    let other = fixture(world, root, "literal_changed");
    let other_binding = policy::Binding::new(producer, other.interface()).unwrap();
    let admission = policy::checked(fixture(world, root, "literal"), producer, &selected).unwrap();
    assert_eq!(admission.emit(&other_binding, &selected, runtime, 0usize).err().unwrap().code, "E_COMPUTATION_BINDING");
    let secret = [11u8; 32];
    let envelope = interface.seal(producer, &secret);
    assert_eq!(policy::authenticated(&wrong, &secret, &envelope, &selected).err().unwrap().code, "E_COMPUTATION_AUTH");
    assert_eq!(policy::authenticated(&expected, &[12u8; 32], &envelope, &selected).err().unwrap().code, "E_COMPUTATION_AUTH");
    assert_eq!(policy::authenticated(&other_binding, &secret, &envelope, &selected).err().unwrap().code, "E_COMPUTATION_AUTH");
    assert!(policy::Binding::new(&[0u8; 31], &interface).is_err());
    assert!(selected.without("future_unknown_operation").is_err());
    9usize
}
fn unknown_operation(world: &mut World, root: &str, producer: &[u8]) -> usize {
    let unit = fixture(world, root, "compute");
    let interface = unit.interface();
    let mut bytes = interface.encode();
    let pattern = b"str_len";
    let replacement = b"str_lex";
    let mut replaced = 0usize;
    for index in 0usize..bytes.len() - pattern.len() + 1usize {
        let mut equal = true;
        for offset in 0usize..pattern.len() { if bytes[index + offset] != pattern[offset] { equal = false; } }
        if equal {
            for offset in 0usize..pattern.len() { bytes[index + offset] = replacement[offset]; }
            replaced += 1usize;
        }
    }
    assert!(replaced > 0usize);
    let secret = [7u8; 32];
    let key = Interface::store_key(interface.name(), interface.input_identity(), interface.dependencies());
    // A deliberately signed future summary exercises the policy's unknown-name
    // default. This is not a claim that the current IR vocabulary can emit it.
    let envelope = reuse::seal(producer, &secret, check::units::STORE_NAMESPACE, &key, &bytes);
    let future = Interface::authenticate(producer, &secret, interface.name(), interface.input_identity(),
        interface.dependencies(), &envelope).unwrap();
    assert!(effect(&future, "str_lex"));
    let expected = policy::Binding::new(producer, &future).unwrap();
    assert_eq!(policy::authenticated(&expected, &secret, &envelope, &policy::computation_v1())
        .err().unwrap().code, "E_COMPUTATION_EFFECT");
    1usize
}
fn import_all(interface: &Interface) -> Import {
    let mut types = Vec::new();
    let mut functions = Vec::new();
    for index in 0usize..interface.program().types.len() { types.push((index, index)); }
    for index in 0usize..interface.program().functions.len() { functions.push((index, index)); }
    Import { interface: interface.clone(), types, functions }
}
fn bridge(interface: &Interface) -> CheckedUnit {
    let mut program = interface.program().clone();
    let called = program.functions.iter().position(|function: &ir::Function| -> bool { function.name == "entry" }).unwrap();
    let mut function = program.functions[called].clone();
    function.name = "bridge::entry".to_string();
    let mut arguments = Vec::new();
    for index in 0usize..function.params { arguments.push(index); }
    let result = function.locals.len();
    function.locals.push(ir::Local { name: "result".to_string(), ty: function.result, mutable: false });
    function.body.push(ir::Instruction { file: None, line: 1usize, column: 1usize,
        op: ir::Op::Call { dst: result, function: called, args: arguments } });
    function.body.push(ir::Instruction { file: None, line: 1usize, column: 1usize,
        op: ir::Op::Return { src: result } });
    let export = program.functions.len();
    program.functions.push(function);
    check::units::check_unit_with_exports("bridge", "bridge-input", program, &[import_all(interface)],
        &[export], &[0usize; 0]).unwrap()
}
fn exact_body_and_dependencies(world: &mut World, root: &str, producer: &[u8]) -> usize {
    let selected = policy::computation_v1();
    let source = fixture(world, root, "literal");
    let interface = source.interface().clone();
    let original = source.program().clone();
    let mut changed = original.clone();
    let entry = changed.functions.iter().position(|function: &ir::Function| -> bool { function.name == "entry" }).unwrap();
    let mut edits = 0usize;
    for index in 0usize..changed.functions[entry].body.len() {
        if let ir::Op::Int { value, .. } = &mut changed.functions[entry].body[index].op { *value += 1i64; edits += 1usize; }
    }
    assert_eq!(edits, 1usize);
    let imports: Vec<Import> = Vec::new();
    let changed = check::units::check_unit_with_exports("literal", interface.input_identity(), changed,
        &imports, &[entry], &[0usize; 0]).unwrap();
    assert_eq!(changed.interface().identity(), interface.identity());
    assert!(changed.interface().body_identity() != interface.body_identity());
    let expected = policy::Binding::new(producer, changed.interface()).unwrap();
    let secret = [6u8; 32];
    assert_eq!(policy::authenticated(&expected, &secret, &interface.seal(producer, &secret), &selected)
        .err().unwrap().code, "E_COMPUTATION_BINDING");
    let first = check::units::check_unit_with_exports("alpha", "provider", original.clone(),
        &imports, &[entry], &[0usize; 0]).unwrap();
    let second = check::units::check_unit_with_exports("beta", "provider", original,
        &imports, &[entry], &[0usize; 0]).unwrap();
    let first = bridge(first.interface());
    let second = bridge(second.interface());
    assert!(first.interface().dependencies() != second.interface().dependencies());
    let expected = policy::Binding::new(producer, second.interface()).unwrap();
    assert_eq!(policy::authenticated(&expected, &secret, &first.interface().seal(producer, &secret), &selected)
        .err().unwrap().code, "E_COMPUTATION_AUTH");
    let foreign = fixture(world, root, "structural_drop");
    let consumer = bridge(foreign.interface());
    assert!(effect(consumer.interface(), "file_close"));
    assert_eq!(policy::checked(consumer, producer, &selected).err().unwrap().code, "E_COMPUTATION_EFFECT");
    3usize
}
pub fn run(world: &mut World, root: &str, compiler: &str) -> usize {
    let producer = producer(compiler);
    let runtime = runtime(world, root);
    positive_and_reuse(world, root, &producer, &runtime)
        + negatives(world, root, &producer)
        + callback_positive(world, root, &producer, &runtime)
        + binding_and_policy_changes(world, root, &producer, &runtime)
        + unknown_operation(world, root, &producer)
        + exact_body_and_dependencies(world, root, &producer)
}

operations.source:
fn main(mut world: World) {
    let arguments = world.args();
    assert_eq!(arguments.len(), 3usize);
    let root = String::from_utf8(arguments[1usize].clone()).unwrap();
    let compiler = String::from_utf8(arguments[2usize].clone()).unwrap();
    let count = programs_unit_policy_cases::run(&mut world, root.as_str(), compiler.as_str());
    world.stdout().write(format!("ok concrete computation {count} controls\n").as_bytes());
}

fn main(mut world: World) {
    let arguments = world.args();
    assert_eq!(arguments.len(), 2usize);
    let root = String::from_utf8(arguments[0usize].clone()).unwrap();
    let compiler = String::from_utf8(arguments[1usize].clone()).unwrap();
    let count = programs_unit_policy_cases::run(&mut world, root.as_str(), compiler.as_str());
    world.stdout().write(format!("ok concrete computation {count} controls\n").as_bytes());
}

pub fn object_key(interface: &Interface, context: &Context<'_>, source_base: usize, sources: &[String]) -> String {
    let mut bytes = b"lkjscript-unit-native-object-1\0"[..].to_vec();
    string(&mut bytes, interface.name()); string(&mut bytes, interface.identity());
    string(&mut bytes, interface.body_identity()); string(&mut bytes, interface.input_identity());
    string(&mut bytes, &context.identity); word(&mut bytes, source_base);
    word(&mut bytes, sources.len());
    for path in sources { string(&mut bytes, path); }
    crate::sha256::hex_digest(&bytes)
}

impl Object {
    pub fn key(&self) -> &str { &self.key }
    pub fn bytes(&self) -> usize { self.code_length }
    fn code_bytes(&self) -> &[u8] {
        if self.payload.is_empty() { return self.code.bytes.as_slice(); }
        &self.payload[self.code_start..self.code_start + self.code_length]
    }
    pub fn encode(&self) -> Vec<u8> {
        let mut bytes = b"LKJUNITOBJECT1\n"[..].to_vec();
        string(&mut bytes, &self.key); string(&mut bytes, &self.context);
        word(&mut bytes, self.source_base); word(&mut bytes, self.flags as usize);
        word(&mut bytes, self.sources.len());
        for path in &self.sources { string(&mut bytes, path); }
        word(&mut bytes, self.messages.len());
        for message in &self.messages { string(&mut bytes, message); }
        word(&mut bytes, self.sites.len());
        for (name, value) in &self.sites { string(&mut bytes, name); site(&mut bytes, *value); }
        blob(&mut bytes, self.code_bytes());
        word(&mut bytes, self.code.definitions.len());
        for (name, offset) in &self.code.definitions { string(&mut bytes, name); word(&mut bytes, *offset); }
        word(&mut bytes, self.code.references.len());
        for reference in &self.code.references { word(&mut bytes, reference.at); string(&mut bytes, &reference.name); site(&mut bytes, reference.site); }
        word(&mut bytes, self.code.immediates.len());
        for reference in &self.code.immediates { word(&mut bytes, reference.at); string(&mut bytes, &reference.message); site(&mut bytes, reference.site); }
        bytes
    }
    pub fn open(domain: &ProofDomain, interface: &Interface, context: &Context<'_>,
        source_base: usize, sources: &[String], payload: VerifiedPayload,
    ) -> Option<Self> {
        let key = object_key(interface, context, source_base, sources);
        if !payload.matches_domain(domain, NAMESPACE, &key) { return None; }
        let bytes = payload.into_bytes();
        let magic = b"LKJUNITOBJECT1\n";
        if !bytes.starts_with(magic) { return None; }
        let mut at = magic.len();
        if take_string(&bytes, &mut at)? != key { return None; }
        let stored_context = take_string(&bytes, &mut at)?;
        if stored_context != context.identity || take_word(&bytes, &mut at)? != source_base { return None; }
        let flags = take_word(&bytes, &mut at)? as u64;
        if flags & !0x1ffffu64 != 0u64 { return None; }
        let count = take_word(&bytes, &mut at)?;
        if count != sources.len() || count > (bytes.len() - at) / 8usize { return None; }
        let mut own_sources = Vec::new();
        for index in 0usize..count {
            let path = take_string(&bytes, &mut at)?;
            if path != sources[index] { return None; }
            own_sources.push(path);
        }
        let count = take_word(&bytes, &mut at)?;
        if count > (bytes.len() - at) / 16usize { return None; }
        let mut own_messages = Vec::new();
        for _ in 0usize..count {
            let message = take_string(&bytes, &mut at)?;
            own_messages.push(message);
        }
        let claim = claim(interface);
        let count = take_word(&bytes, &mut at)?;
        if count != claim.definitions.len() || count > (bytes.len() - at) / 32usize { return None; }
        let mut sites = Vec::new();
        for index in 0usize..count {
            let name = take_string(&bytes, &mut at)?;
            let value = take_site(&bytes, &mut at)?;
            if name != claim.definitions[index] || value.file < source_base || value.file - source_base >= sources.len() { return None; }
            sites.push((name, value));
        }
        // Keep the exact already-authenticated owned bytes. Cloning this span
        // would copy every code byte again on every unchanged build.
        let code_length = take_word(&bytes, &mut at)?;
        if code_length > bytes.len() - at { return None; }
        let code_start = at;
        at += code_length;
        let count = take_word(&bytes, &mut at)?;
        if count != claim.definitions.len() || count > (bytes.len() - at) / 16usize { return None; }
        let mut definitions = Vec::new();
        for index in 0usize..count {
            let name = take_string(&bytes, &mut at)?;
            let offset = take_word(&bytes, &mut at)?;
            if name != claim.definitions[index] || offset >= code_length { return None; }
            definitions.push((name, offset));
        }
        let count = take_word(&bytes, &mut at)?;
        if count > (bytes.len() - at) / 40usize { return None; }
        let mut references = Vec::new();
        let mut previous = None;
        for _ in 0usize..count {
            let position = take_word(&bytes, &mut at)?;
            let name = take_string(&bytes, &mut at)?;
            let value = take_site(&bytes, &mut at)?;
            if position > code_length || code_length - position < 4usize || value.file < source_base || value.file - source_base >= sources.len()
                || previous.is_some_and(|last| last + 4usize > position) { return None; }
            previous = Some(position);
            references.push(SymbolReference { at: position, name, site: value });
        }
        let count = take_word(&bytes, &mut at)?;
        if count > (bytes.len() - at) / 40usize { return None; }
        let mut immediates = Vec::new();
        for _ in 0usize..count {
            let position = take_word(&bytes, &mut at)?;
            let message = take_string(&bytes, &mut at)?;
            let value = take_site(&bytes, &mut at)?;
            if position > code_length || code_length - position < 8usize || value.file < source_base
                || value.file - source_base >= sources.len() || !own_messages.contains(&message) { return None; }
            immediates.push(ImmediateReference { at: position, message, site: value });
        }
        if at != bytes.len() { return None; }
        Some(Self { claim, context: stored_context, key, source_base, flags, sites, sources: own_sources, messages: own_messages,
            code: Linkable { bytes: Vec::new(), definitions, references, immediates }, payload: bytes, code_start, code_length })
    }
}

pub fn emit(unit: &CheckedUnit, context: &Context<'_>, source_base: usize) -> Result<Object, Diagnostic> {
    let runtime = context.runtime;
    let program = unit.program();
    if program.sources.len().max(1usize) > (!0usize) - source_base { return Err(error("unit source table extent overflow")); }
    let messages = super::messages(program);
    let layout = Layouts::new(program)?;
    if unit.layouts().len() != program.types.len() { return Err(error("unit layout inventory differs")); }
    for (index, expected) in unit.layouts().iter().enumerate() {
        let actual = layout.storage(index);
        if actual.bytes != expected.bytes || actual.alignment != expected.alignment
            || actual.fields != expected.fields || actual.variants != expected.variants
            || actual.scalar != expected.scalar || actual.signed != expected.signed || actual.cleanup != expected.cleanup {
            return Err(error("native layout disagrees with the authenticated unit layout"));
        }
    }
    let mut a = Assembler::new();
    a.enable_symbolic_messages();
    let p = platform::Platform::new(&mut a);
    let mut names = Vec::new();
    for index in 0usize..a.label_count() { names.push((index, platform_symbol(index))); }
    let runtime_functions = labels(&mut a, runtime.checked_program().functions.len());
    for (index, function) in runtime.checked_program().functions.iter().enumerate() {
        names.push((runtime_functions[index], runtime_symbol(&function.name)));
    }
    let functions = labels(&mut a, program.functions.len());
    for index in 0usize..functions.len() {
        if unit.imported(index) || unit.exported(index) { names.push((functions[index], symbol(&unit.binding(index)))); }
    }
    let drops = labels(&mut a, program.types.len());
    let runtime_labels = RuntimeLabels::new(runtime, &runtime_functions);
    let mut needed = vec![false; functions.len()];
    let mut needed_drops = vec![false; drops.len()];
    let mut emitted_drops = vec![false; drops.len()];
    let mut literals = BTreeMap::new();
    let mut sites = Vec::new();
    let selection = Selection { program, layout: &layout, functions: &functions, drops: &drops,
        runtime: runtime_labels, messages: &messages, source_base };
    for index in 0usize..functions.len() {
        if !unit.imported(index) {
            let mut site = first_site(&program.functions[index]); site.file += source_base;
            if unit.exported(index) { sites.push((symbol(&unit.binding(index)), site)); }
            emit_function(&mut a, p, &selection, index, &mut needed, &mut needed_drops, &mut literals)?;
        }
    }
    loop {
        let mut progress = false;
        for ty in 0usize..drops.len() {
            if needed_drops[ty] && !emitted_drops[ty] {
                emitted_drops[ty] = true; progress = true;
                emit_drop(&mut a, p, &selection, ty, &mut needed_drops, &mut needed)?;
            }
        }
        if !progress { break; }
    }
    for (bytes, label) in &literals { a.bind(*label); a.raw(bytes); }
    let mut code = a.linkable(&names)?;
    let claim = claim(unit.interface());
    let mut by_name = BTreeMap::new();
    for (name, offset) in code.definitions { by_name.insert(name, offset); }
    code.definitions = Vec::new();
    let mut by_site = BTreeMap::new();
    for (name, value) in sites { by_site.insert(name, value); }
    sites = Vec::new();
    for name in &claim.definitions {
        let offset = *by_name.get(name).ok_or_else(|| error("exported function has no code"))?;
        let value = *by_site.get(name).ok_or_else(|| error("exported function has no source site"))?;
        code.definitions.push((name.clone(), offset)); sites.push((name.clone(), value));
    }
    let own_sources = if program.sources.is_empty() { vec!["<ir>".to_string()] } else { program.sources.clone() };
    let mut own_messages: Vec<String> = Vec::new();
    for reference in &code.immediates {
        if !own_messages.contains(&reference.message) { own_messages.push(reference.message.clone()); }
    }
    let code_length = code.bytes.len();
    Ok(Object { claim, context: context.identity.clone(),
        key: object_key(unit.interface(), context, source_base, &own_sources), source_base,
        flags: features(program), sites, sources: own_sources, messages: own_messages, code,
        payload: Vec::new(), code_start: 0usize, code_length })
}

impl Linker {
    pub fn new(mut output: File, mut relocations: File) -> Result<Self, Diagnostic> {
        output.truncate(0usize).map_err(|errno: i64| io("truncate unit output", errno))?;
        output.seek(0i64, 0u8).map_err(|errno: i64| io("seek unit output", errno))?;
        relocations.truncate(0usize).map_err(|errno: i64| io("truncate relocation spool", errno))?;
        relocations.seek(0i64, 0u8).map_err(|errno: i64| io("seek relocation spool", errno))?;
        output.write_all(&vec![0u8; platform::CODE_OFFSET]).map_err(|errno: i64| io("reserve ELF header", errno))?;
        output.write_all(&[0xe9u8, 0u8, 0u8, 0u8, 0u8]).map_err(|errno: i64| io("write entry branch", errno))?;
        let mut result = Self { output, position: 5usize, context: None, flags: 0u64,
            claims: BTreeMap::new(), symbols: BTreeMap::new(), sites: BTreeMap::new(),
            relocations, reference_count: 0usize, relocation_bytes: 0usize, relocation_hash: crate::sha256::Sha256::new(), failed: false,
            tables: Vec::new() };
        result.reference(0usize, 1usize, "entry", Span::default())?;
        Ok(result)
    }
    fn reference(&mut self, kind: usize, position: usize, name: &str, value: Span) -> Result<(), Diagnostic> {
        let mut record = Vec::new();
        word(&mut record, kind); word(&mut record, position); string(&mut record, name); site(&mut record, value);
        self.records(&record, 1usize)
    }
    fn records(&mut self, records: &[u8], count: usize) -> Result<(), Diagnostic> {
        if records.is_empty() { return Ok(()); }
        let next = self.relocation_bytes.checked_add(records.len()).ok_or_else(|| error("relocation spool extent overflow"))?;
        if next > 9223372036854775807usize { return Err(error("relocation spool exceeds file seek representation")); }
        self.relocations.seek(self.relocation_bytes as i64, 0u8).map_err(|errno: i64| io("seek relocation append", errno))?;
        self.relocations.write_all(records).map_err(|errno: i64| io("write relocation spool", errno))?;
        self.relocation_hash.update(records);
        self.relocation_bytes = next;
        self.reference_count += count;
        Ok(())
    }
    fn append(&mut self, code: &Linkable, bytes: &[u8]) -> Result<(), Diagnostic> {
        let next = self.position.checked_add(bytes.len()).ok_or_else(|| error("unit image extent overflow"))?;
        if next > 9223372036854775807usize - platform::CODE_OFFSET { return Err(error("unit image exceeds file seek representation")); }
        for (name, offset) in &code.definitions {
            if *offset > bytes.len() || self.symbols.contains_key(name) {
                return Err(error(&format!("duplicate or out-of-range unit symbol {name}")));
            }
            self.symbols.insert(name.clone(), self.position + *offset);
        }
        let mut records = Vec::new();
        let mut count = 0usize;
        for reference in &code.references {
            if reference.at > bytes.len() || bytes.len() - reference.at < 4usize {
                return Err(error("unit relocation is outside its object"));
            }
            word(&mut records, 0usize); word(&mut records, self.position + reference.at);
            string(&mut records, &reference.name); site(&mut records, reference.site); count += 1usize;
        }
        for reference in &code.immediates {
            if reference.at > bytes.len() || bytes.len() - reference.at < 8usize { return Err(error("unit message relocation is outside its object")); }
            word(&mut records, 1usize); word(&mut records, self.position + reference.at);
            string(&mut records, &reference.message); site(&mut records, reference.site); count += 1usize;
        }
        self.records(&records, count)?;
        let position = self.position + platform::CODE_OFFSET;
        self.output.seek(position as i64, 0u8).map_err(|errno: i64| io("seek unit object", errno))?;
        self.output.write_all(bytes).map_err(|errno: i64| io("write unit object", errno))?;
        self.position = next;
        Ok(())
    }
    pub fn push(&mut self, object: Object) -> Result<(), Diagnostic> {
        if self.failed { return Err(error("unit linker is poisoned by an earlier failure")); }
        self.failed = true;
        let result = self.push_object(object);
        if result.is_ok() { self.failed = false; }
        result
    }
    fn push_object(&mut self, object: Object) -> Result<(), Diagnostic> {
        let existing_context = self.context.clone();
        if let Some(context) = existing_context {
            if context != object.context { return Err(error("unit objects use different runtime or target identities")); }
        } else { self.context = Some(object.context.clone()); }
        if self.claims.contains_key(&object.claim.name) {
            return Err(error(&format!("duplicate unit implementation {}", object.claim.name)));
        }
        if object.code.definitions.len() != object.claim.definitions.len() {
            return Err(error("unit object does not define its complete checked interface"));
        }
        for (index, (name, _)) in object.code.definitions.iter().enumerate() {
            if *name != object.claim.definitions[index] { return Err(error("unit object export differs from checked interface")); }
        }
        self.append(&object.code, object.code_bytes())?;
        self.flags |= object.flags;
        for (name, site) in object.sites { self.sites.insert(name, site); }
        self.tables.push(Tables { source_base: object.source_base, sources: object.sources, messages: object.messages });
        self.claims.insert(object.claim.name.clone(), object.claim);
        Ok(())
    }
    pub fn finish(mut self, context: &Context<'_>, entry: &Interface, entry_name: &str,
        grants: &[ir::EntryGrant], sources: &[String], messages: &[String], result_fd: Option<u32>,
    ) -> Result<(File, usize), Diagnostic> {
        let runtime = context.runtime;
        if self.failed { return Err(error("unit linker is poisoned by an earlier failure")); }
        if self.context.as_ref() != Some(&context.identity) {
            return Err(error("linked runtime differs from unit object runtime"));
        }
        let entry_unit_name = entry.name().to_string();
        let selected_claim = self.claims.get(&entry_unit_name).ok_or_else(|| error("entry unit has no implementation"))?;
        if selected_claim.interface.as_str() != entry.identity() || selected_claim.body.as_str() != entry.body_identity() {
            return Err(error("entry interface or implementation is stale"));
        }
        for (_, claim) in &self.claims {
            for (name, identity) in &claim.dependencies {
                let actual = self.claims.get(name).ok_or_else(|| error(&format!("unit {} is missing dependency {name}", claim.name)))?;
                if actual.interface != *identity { return Err(error(&format!("unit {} has a stale dependency interface {name}", claim.name))); }
            }
            for imported in &claim.imports {
                if !self.symbols.contains_key(imported) { return Err(error(&format!("unit {} has no exact implementation for {imported}", claim.name))); }
            }
        }
        for table in &self.tables {
            if table.source_base > sources.len() || table.sources.len() > sources.len() - table.source_base {
                return Err(error("unit source table does not fit the final image"));
            }
            for (index, path) in table.sources.iter().enumerate() {
                if *path != sources[table.source_base + index] { return Err(error("unit source table changed after emission")); }
            }
            for message in &table.messages {
                if !messages.contains(message) { return Err(error("unit trap message is absent from the final image")); }
            }
        }
        let mut message_set: BTreeSet<String> = BTreeSet::new();
        for message in messages { message_set.insert(message.clone()); }
        let mut message_names = Vec::new();
        let mut message_codes = BTreeMap::new();
        for message in message_set {
            message_codes.insert(message.clone(), message_names.len() + 16usize);
            message_names.push(message);
        }
        let program = entry.program();
        let selected = program.functions.iter().position(|function| function.name == entry_name)
            .ok_or_else(|| error(&format!("unknown unit entry {entry_name}")))?;
        if !entry.defined(selected) { return Err(error("entry must be defined by its selected unit")); }
        let binding = symbol(&entry.binding(selected));
        let site = *self.sites.get(&binding).ok_or_else(|| error("entry site has no implementation"))?;
        let (support, data_offset) = support(runtime, program, selected, &binding, site, grants,
            sources, &message_names, result_fd, self.flags, self.position)?;
        self.append(&support, &support.bytes)?;
        self.relocations.seek(0i64, 0u8).map_err(|errno: i64| io("rewind relocation spool", errno))?;
        let expected_hash = std::mem::replace(&mut self.relocation_hash, crate::sha256::Sha256::new()).finish();
        {
            let mut records = Relocations::new(&mut self.relocations, self.relocation_bytes);
            let mut patches = PatchWindow::new(&mut self.output, platform::CODE_OFFSET + self.position);
            for _ in 0usize..self.reference_count {
                let (kind, position, name, site) = records.record()?;
                let width = if kind == 0usize { 4usize } else if kind == 1usize { 8usize } else { return Err(error("unknown unit relocation kind")); };
                if position > data_offset || width > data_offset - position { return Err(error("unit relocation is outside image code")); }
                let bytes = if kind == 0usize {
                    let target = *self.symbols.get(&name)
                        .ok_or_else(|| Diagnostic::new(site, "E_UNIT_LINK", &format!("unresolved unit symbol {name}")))?;
                    crate::x86::displacement(target, position, site)?[..].to_vec()
                } else {
                    let code = *message_codes.get(&name).ok_or_else(|| error("unit message relocation is absent from final table"))?;
                    let mut bytes = Vec::new(); word(&mut bytes, code); bytes
                };
                patches.write(platform::CODE_OFFSET + position, &bytes)?;
            }
            records.finish(expected_hash)?;
            patches.flush()?;
        }
        let header = platform::elf_header(self.position, data_offset)?;
        self.output.seek(0i64, 0u8).map_err(|errno: i64| io("seek ELF header", errno))?;
        self.output.write_all(&header).map_err(|errno: i64| io("write ELF header", errno))?;
        let length = platform::CODE_OFFSET + self.position;
        self.output.seek(length as i64, 0u8).map_err(|errno: i64| io("seek finished image", errno))?;
        Ok((self.output, length))
    }
}

pub struct Context<'a> {
    runtime: &'a Runtime,
    identity: String,
}

impl<'a> Context<'a> {
    pub fn new(runtime: &'a Runtime) -> Self {
